// Lógica do fluxo "eLabFTW – Depósito no Zenodo".
// decidirDepositos: escolhe os Produtos a depositar e monta os metadados do Zenodo; avisa o dono do que falta.
// emailsDoDeposito: depois de criado o rascunho, monta o e-mail para a conta do Instituto (com cópia ao dono).
// O fluxo só cria rascunhos; nunca publica.

const DIA = 24 * 3600e3;

function camposDe(x) {
  let m = x.metadata_decoded || x.metadata;
  if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch (e) { m = {}; }
  }
  return (m && m.extra_fields) || {};
}

function valor(x, nome) {
  const c = camposDe(x)[nome];
  return c && c.value !== undefined && c.value !== null ? String(c.value).trim() : '';
}

const ORCID = /^\d{4}-\d{4}-\d{4}-\d{3}[\dX]$/;

function autoresDe(texto) {
  const autores = [];
  const erros = [];
  for (const linha of String(texto || '').split(/\r?\n|\|/).map((l) => l.trim()).filter(Boolean)) {
    const [nome, vinculo, orcid] = linha.split(';').map((p) => (p || '').trim());
    if (!/^[^,]+,\s*\S/.test(nome || '')) {
      erros.push(`"${linha}": o nome precisa estar no formato "Sobrenome, Nome"`);
      continue;
    }
    const a = { name: nome };
    if (vinculo) a.affiliation = vinculo;
    if (orcid) {
      const o = orcid.replace(/^https?:\/\/orcid\.org\//, '');
      if (ORCID.test(o)) a.orcid = o;
      else erros.push(`"${linha}": ORCID inválido (formato 0000-0000-0000-0000)`);
    }
    autores.push(a);
  }
  return { autores, erros };
}

function escHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
}

const TIPOS = {
  'Relatório técnico (série RT-Modal)': { upload_type: 'publication', publication_type: 'report' },
  'Relatório para financiador': { upload_type: 'publication', publication_type: 'report' },
  Artigo: { upload_type: 'publication', publication_type: 'article' },
  'Trabalho acadêmico': { upload_type: 'publication', publication_type: 'thesis' },
  'Livro ou capítulo': { upload_type: 'publication', publication_type: 'book' },
  'Registro de programa de computador': { upload_type: 'software' },
  'Dados ou código abertos': { upload_type: 'dataset' },
};

function pdfMaisRecente(x) {
  const pdfs = (x.uploads || []).filter((u) => u && /\.pdf$/i.test(u.real_name || ''));
  pdfs.sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')) || Number(b.id) - Number(a.id));
  return pdfs[0] || null;
}

function urlProduto(cfg, id) {
  return `${cfg.urlPublica}/database.php?mode=view&id=${id}`;
}

function decidirDepositos({ produtos, usuarios, depositos, avisos, hoje, cfg }) {
  const usuario = new Map(usuarios.filter((u) => u && u.userid !== undefined).map((u) => [String(u.userid), u]));
  const feito = new Set(depositos.filter((d) => d && d.produto_id !== undefined && d.produto_id !== null).map((d) => String(d.produto_id)));
  const avisado = new Map(avisos.filter((a) => a && a.chave).map((a) => [String(a.chave), a]));
  const testador = usuario.get(String(cfg.usuarioTesteId));
  if (cfg.modoTeste && !(testador && testador.email)) {
    throw new Error(`Modo de teste: usuário ${cfg.usuarioTesteId} sem e-mail legível pela API; nada foi feito.`);
  }
  const saida = [];

  for (const x of produtos) {
    if (!x || x.id === undefined || x.category_title !== cfg.categoriaProduto) continue;
    if (!/^(on|1|true)$/i.test(valor(x, cfg.campoMarcar))) continue;
    if (feito.has(String(x.id))) continue;
    if (cfg.modoTeste && !(cfg.produtosTeste || []).map(Number).includes(Number(x.id))) continue;
    if (valor(x, cfg.campoDoi)) continue;

    const { autores, erros } = autoresDe(valor(x, cfg.campoAutores));
    const resumo = valor(x, cfg.campoResumo);
    const pdf = pdfMaisRecente(x);
    const faltas = [];
    if (!String(x.title || '').trim()) faltas.push('Título do Produto');
    if (!autores.length && !erros.length) faltas.push(`Campo "${cfg.campoAutores}" (autores separados por |, cada um como Sobrenome, Nome; vínculo; ORCID)`);
    faltas.push(...erros.map((e) => `Autor ${e}`));
    if (!resumo) faltas.push(`Campo "${cfg.campoResumo}"`);
    if (!pdf) faltas.push('PDF anexado ao Produto');

    const dono = usuario.get(String(x.userid));
    const real = dono && dono.email ? dono.email : '';
    const nome = (dono && dono.fullname) || 'pesquisador(a)';
    const para = cfg.modoTeste ? testador.email : real;

    if (faltas.length) {
      const chave = `p${x.id}:faltas:${faltas.join('|')}`.slice(0, 250);
      const anterior = avisado.get(chave);
      if (anterior && anterior.ultimo_aviso && hoje - new Date(anterior.ultimo_aviso) < cfg.repetirDias * DIA) continue;
      const registro = { chave, produto_id: Number(x.id), ultimo_aviso: hoje.toISOString() };
      if (!para) {
        saida.push({ acao: 'sem-destinatario', ...registro });
        continue;
      }
      const blocos = [
        { tipo: 'paragrafo', texto: `Olá, ${nome}.` },
        { tipo: 'paragrafo', texto: `O Produto "${x.title}" está marcado para depósito no Zenodo, mas falta o seguinte. Nada foi enviado ao Zenodo.` },
        { tipo: 'lista', itens: faltas },
        { tipo: 'paragrafo', texto: 'Complete o Produto no eLabFTW; o depósito sai na próxima conferência.' },
      ];
      if (cfg.modoTeste) blocos.push({ tipo: 'aviso', tom: 'atencao', texto: `Modo de teste: este aviso iria para ${nome}${real ? ` (${real})` : ' (sem e-mail)'}.` });
      saida.push({
        acao: 'avisar', ...registro, para,
        nomeRemetente: 'PD&I Modal', responderPara: 'pesquisa@modal.org.br',
        assunto: `${cfg.modoTeste ? '[TESTE] ' : ''}eLabFTW: falta informação para depositar "${x.title}" no Zenodo`,
        etiqueta: 'eLabFTW · Depósito no Zenodo',
        titulo: 'Falta informação para o depósito no Zenodo',
        blocos, acaoRotulo: 'Abrir o Produto', acaoUrl: urlProduto(cfg, x.id),
        rodape: 'Depósito automático no Zenodo (Diretrizes, seção 8). Dúvidas: pesquisa@modal.org.br.',
      });
      continue;
    }

    const tipo = TIPOS[valor(x, cfg.campoTipo)] || { upload_type: 'publication', publication_type: 'other' };
    const palavras = valor(x, cfg.campoPalavras).split(/[;\n]/).map((p) => p.trim()).filter(Boolean);
    const identificador = valor(x, cfg.campoIdentificador);
    const metadata = {
      ...tipo,
      title: String(x.title).trim(),
      creators: autores,
      description: resumo.split(/\r?\n\s*\r?\n/).map((p) => `<p>${escHtml(p.trim())}</p>`).join(''),
      access_right: 'open',
      license: cfg.licenca,
      language: cfg.idioma,
      imprint_publisher: cfg.editora,
      communities: cfg.comunidade ? [{ identifier: cfg.comunidade }] : [],
      prereserve_doi: true,
      ...(palavras.length ? { keywords: palavras } : {}),
      ...(identificador ? { notes: identificador } : {}),
    };
    saida.push({
      acao: 'depositar',
      produto_id: Number(x.id),
      titulo: String(x.title).trim(),
      identificador,
      dono_id: Number(x.userid),
      upload_id: Number(pdf.id),
      arquivo: pdf.real_name,
      metadata,
      metadata_elab: typeof x.metadata === 'string' ? x.metadata : JSON.stringify(x.metadata || {}),
    });
  }
  return saida;
}

function emailsDoDeposito({ deposito, zenodo, usuarios, cfg }) {
  const usuario = new Map(usuarios.filter((u) => u && u.userid !== undefined).map((u) => [String(u.userid), u]));
  const testador = usuario.get(String(cfg.usuarioTesteId));
  const dono = usuario.get(String(deposito.dono_id));
  const doi = (zenodo.metadata && zenodo.metadata.prereserve_doi && zenodo.metadata.prereserve_doi.doi) || '';
  // endereço atual do rascunho; links.html traz o antigo /deposit/<id>, que só redireciona
  const link = `${cfg.urlZenodo}/uploads/${zenodo.id}`;
  const m = deposito.metadata;
  const destino = cfg.modoTeste ? testador.email : cfg.revisor;
  const copia = cfg.modoTeste ? '' : (dono && dono.email) || '';
  const blocos = [
    { tipo: 'paragrafo', texto: `O Produto "${deposito.titulo}" foi enviado ao Zenodo como rascunho, na conta do Instituto. Nada foi publicado.` },
    { tipo: 'campos', titulo: 'Prévia do depósito', itens: [
      ...(deposito.identificador ? [{ rotulo: 'Identificador', valor: deposito.identificador }] : []),
      { rotulo: 'Título', valor: m.title },
      { rotulo: 'Autores', valor: m.creators.map((c) => c.name).join('; ') },
      { rotulo: 'DOI reservado', valor: doi || '(não informado pelo Zenodo)' },
      { rotulo: 'Arquivo', valor: deposito.arquivo },
      { rotulo: 'Licença', valor: m.license },
      { rotulo: 'Comunidade', valor: (m.communities[0] && m.communities[0].identifier) || '-' },
      { rotulo: 'Produto no eLabFTW', valor: 'abrir', url: urlProduto(cfg, deposito.produto_id) },
    ] },
    { tipo: 'subtitulo', texto: 'Para publicar' },
    { tipo: 'lista', itens: [
      `Entre no Zenodo com a conta do Instituto (${cfg.revisor}) e abra o rascunho pelo botão abaixo.`,
      'Confira o PDF, os autores, o resumo e a licença. O DOI só passa a valer depois de publicado e não se desfaz.',
      'Clique em Publish. Para corrigir depois, crie uma nova versão no mesmo registro.',
    ] },
    { tipo: 'paragrafo', texto: `O DOI reservado já foi gravado no Produto. Cópia para ${(dono && dono.fullname) || 'o dono do Produto'}, que não consegue abrir o rascunho com a própria conta.` },
  ];
  if (cfg.modoTeste) blocos.push({ tipo: 'aviso', tom: 'atencao', texto: `Modo de teste (Zenodo de testes): este e-mail iria para ${cfg.revisor}, com cópia para ${(dono && dono.email) || 'o dono do Produto'}.` });
  return {
    para: destino,
    cc: copia,
    nomeRemetente: 'PD&I Modal',
    responderPara: 'pesquisa@modal.org.br',
    assunto: `${cfg.modoTeste ? '[TESTE] ' : ''}Zenodo: rascunho pronto para revisão — ${deposito.titulo}`,
    etiqueta: 'eLabFTW · Depósito no Zenodo',
    titulo: 'Rascunho no Zenodo pronto para revisão',
    blocos,
    acaoRotulo: 'Abrir o rascunho no Zenodo',
    acaoUrl: link,
    rodape: 'Depósito automático no Zenodo (Diretrizes, seção 8). O fluxo só cria rascunhos; a publicação é sempre manual.',
    doi,
    link,
    deposito_id: Number(zenodo.id),
  };
}

function metadadosComDoi(metadataElab, campoDoi, doi) {
  const m = JSON.parse(metadataElab || '{}');
  m.extra_fields = m.extra_fields || {};
  m.extra_fields[campoDoi] = { ...(m.extra_fields[campoDoi] || { type: 'url' }), value: doi ? `https://doi.org/${doi}` : '' };
  return JSON.stringify(m);
}


const dados = (nome) => $(nome).all().map((i) => i.json);
return decidirDepositos({
  produtos: dados('Ler produto completo'),
  usuarios: dados('Ler usuários'),
  depositos: dados('Ler depósitos'),
  avisos: dados('Ler avisos'),
  hoje: new Date(),
  cfg: $('Configuração').first().json,
}).map((json) => ({ json }));

